#include <bits/stdc++.h>
using namespace std;

struct Event {
    long long x;
    int type; // +1 add, -1 remove
    long long y1, y2;
    bool operator<(const Event& other) const {
        if (x != other.x) return x < other.x;
        return type > other.type;
    }
};

struct SegTree {
    int n;
    vector<int> cover;
    vector<long long> len;
    vector<long long> ys;

    SegTree(const vector<long long>& coord) {
        ys = coord;
        n = (int)ys.size() - 1; // intervals
        cover.assign(4 * max(1, n), 0);
        len.assign(4 * max(1, n), 0);
    }

    void pull(int node, int l, int r) {
        if (cover[node] > 0) {
            len[node] = ys[r + 1] - ys[l];
        } else if (l == r) {
            len[node] = 0;
        } else {
            len[node] = len[node << 1] + len[node << 1 | 1];
        }
    }

    void update(int node, int l, int r, int ql, int qr, int val) {
        if (ql > r || qr < l || ql > qr) return;
        if (ql <= l && r <= qr) {
            cover[node] += val;
            pull(node, l, r);
            return;
        }
        int mid = (l + r) >> 1;
        update(node << 1, l, mid, ql, qr, val);
        update(node << 1 | 1, mid + 1, r, ql, qr, val);
        pull(node, l, r);
    }

    void update(int ql, int qr, int val) {
        if (n <= 0 || ql > qr) return;
        update(1, 0, n - 1, ql, qr, val);
    }

    long long query() const {
        return n > 0 ? len[1] : 0;
    }
};

