#include <stdio.h>
#include <stdlib.h>

#define MAX_N 1000

// Structure to represent a rectangle
typedef struct {
    int x1, y1, x2, y2;
} Rect;

// Structure for sweep line event
typedef struct {
    int x;
    int y1, y2;
    int type; // 1 for start, -1 for end
} Event;

// Comparator for sorting events by x coordinate
int cmp_event(const void *a, const void *b) {
    Event *ea = (Event *)a;
    Event *eb = (Event *)b;
    if (ea->x != eb->x)
        return ea->x - eb->x;
    return ea->type - eb->type; // process start before end
}

// Comparator for sorting y coordinates
int cmp_int(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}

// Segment tree node for coverage count
typedef struct {
    int count;  // number of active rectangles covering this segment
    int len;    // length of covered portion
} Node;

Node tree[8 * MAX_N]; // 4 * 2 * MAX_N for safety
int y_coords[2 * MAX_N];
int y_size;

// Build tree initially
void build(int node, int l, int r) {
    tree[node].count = 0;
    tree[node].len = 0;
    if (l == r) return;
    int mid = (l + r) / 2;
    build(node * 2, l, mid);
    build(node * 2 + 1, mid + 1, r);
}

// Update the segment tree for a given y-range
void update(int node, int l, int r, int ql, int qr, int val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        tree[node].count += val;
    } else {
        int mid = (l + r) / 2;
        update(node * 2, l, mid, ql, qr, val);
        update(node * 2 + 1, mid + 1, r, ql, qr, val);
    }
    // Update length
    if (tree[node].count > 0) {
        tree[node].len = y_coords[r + 1] - y_coords[l];
    } else if (l == r) {
        tree[node].len = 0;
    } else {
        tree[node].len = tree[node * 2].len + tree[node * 2 + 1].len;
    }
}

int main() {
    int n;
    while (1) {
        scanf("%d", &n);
        if (n == 0) break;

        Rect rects[MAX_N];
        Event events[2 * MAX_N];
        y_size = 0;

        for (int i = 0; i < n; i++) {
            int x, y, r;
            scanf("%d %d %d", &x, &y, &r);
            // L-infinity square: center (x,y), half-side r
            rects[i].x1 = x - r;
            rects[i].y1 = y - r;
            rects[i].x2 = x + r;
            rects[i].y2 = y + r;

            // Events for sweep line
            events[2 * i].x = rects[i].x1;
            events[2 * i].y1 = rects[i].y1;
            events[2 * i].y2 = rects[i].y2;
            events[2 * i].type = 1;

            events[2 * i + 1].x = rects[i].x2;
            events[2 * i + 1].y1 = rects[i].y1;
            events[2 * i + 1].y2 = rects[i].y2;
            events[2 * i + 1].type = -1;

            // Collect y coordinates
            y_coords[y_size++] = rects[i].y1;
            y_coords[y_size++] = rects[i].y2;
        }

        // Sort and deduplicate y coordinates
        qsort(y_coords, y_size, sizeof(int), cmp_int);
        int unique_y = 0;
        for (int i = 0; i < y_size; i++) {
            if (i == 0 || y_coords[i] != y_coords[i - 1]) {
                y_coords[unique_y++] = y_coords[i];
            }
        }
        y_size = unique_y;

        // Build segment tree over compressed y coordinates
        build(1, 0, y_size - 2); // intervals between y_coords

        // Sort events by x
        qsort(events, 2 * n, sizeof(Event), cmp_event);

        long long total_area = 0;
        int prev_x = events[0].x;

        for (int i = 0; i < 2 * n; i++) {
            int cur_x = events[i].x;
            // Add area from previous x to current x
            total_area += (long long)tree[1].len * (cur_x - prev_x);

            // Find compressed y indices
            int y1_idx = -1, y2_idx = -1;
            for (int j = 0; j < y_size; j++) {
                if (y_coords[j] == events[i].y1) y1_idx = j;
                if (y_coords[j] == events[i].y2) y2_idx = j;
            }
            // Update segment tree for this event
            update(1, 0, y_size - 2, y1_idx, y2_idx - 1, events[i].type);

            prev_x = cur_x;
        }

        printf("%lld\n", total_area);
    }
    return 0;
}

