typedef struct { double x1, y1, x2, y2; } Rect;

int cmp_double(const void *a, const void *b) {
    double da = *(double*)a, db = *(double*)b;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

int cmp_interval(const void *a, const void *b) {
    double *ia = (double*)a, *ib = (double*)b;
    if (ia[0] < ib[0]) return -1;
    if (ia[0] > ib[0]) return 1;
    return 0;
}

double compute_y_coverage(double intervals[][2], int cnt) {
    if (cnt == 0) return 0;
    qsort(intervals, cnt, sizeof(intervals[0]), cmp_interval);
    double total = 0, cur_start = intervals[0][0], cur_end = intervals[0][1];
    for (int i = 1; i < cnt; i++) {
        if (intervals[i][0] <= cur_end) {
            if (intervals[i][1] > cur_end) cur_end = intervals[i][1];
        } else {
            total += cur_end - cur_start;
            cur_start = intervals[i][0];
            cur_end = intervals[i][1];
        }
    }
    total += cur_end - cur_start;
    return total;
}

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        Rect rects[1000];
        double xs[2000];
        int xc = 0;
        for (int i = 0; i < n; i++) {
            double x, y, r;
            scanf("%lf %lf %lf", &x, &y, &r);
            rects[i].x1 = x - r; rects[i].x2 = x + r;
            rects[i].y1 = y - r; rects[i].y2 = y + r;
            xs[xc++] = rects[i].x1;
            xs[xc++] = rects[i].x2;
        }
        qsort(xs, xc, sizeof(double), cmp_double);
        // deduplicate
        int uxc = 0;
        for (int i = 0; i < xc; i++) {
            if (uxc == 0 || xs[i] != xs[uxc-1]) xs[uxc++] = xs[i];
        }

        double total_area = 0;
        double intervals[1000][2];
        for (int i = 0; i + 1 < uxc; i++) {
            double mx = (xs[i] + xs[i+1]) / 2.0;
            int cnt = 0;
            for (int j = 0; j < n; j++) {
                if (rects[j].x1 <= mx && mx <= rects[j].x2) {
                    intervals[cnt][0] = rects[j].y1;
                    intervals[cnt][1] = rects[j].y2;
                    cnt++;
                }
            }
            double ycov = compute_y_coverage(intervals, cnt);
            total_area += (xs[i+1] - xs[i]) * ycov;
        }
        printf("%.0f\n", total_area);
    }
    return 0;
}

