typedef long long ll;

typedef struct {
    ll x1, x2, y1, y2;
} Rect;

typedef struct {
    ll x;
    int type;   /* +1 add, -1 remove */
    ll y1, y2;
} Event;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int cmp_event(const void *a, const void *b) {
    const Event *e1 = (const Event *)a;
    const Event *e2 = (const Event *)b;
    if (e1->x < e2->x) return -1;
    if (e1->x > e2->x) return 1;
    /* process additions before removals at same x */
    if (e1->type > e2->type) return -1;
    if (e1->type < e2->type) return 1;
    return 0;
}

static int lower_bound_ll(ll *arr, int n, ll val) {
    int l = 0, r = n;
    while (l < r) {
        int m = l + (r - l) / 2;
        if (arr[m] < val) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
