            scanf("%lld %lld %lld", &x, &y, &r);
            rects[i].x1 = x - r;
            rects[i].x2 = x + r;
            rects[i].y1 = y - r;
            rects[i].y2 = y + r;

            events[2 * i].x = rects[i].x1;
            events[2 * i].type = +1;
            events[2 * i].y1 = rects[i].y1;
            events[2 * i].y2 = rects[i].y2;

            events[2 * i + 1].x = rects[i].x2;
            events[2 * i + 1].type = -1;
            events[2 * i + 1].y1 = rects[i].y1;
            events[2 * i + 1].y2 = rects[i].y2;

            ys[2 * i] = rects[i].y1;
            ys[2 * i + 1] = rects[i].y2;
        }

        qsort(events, 2 * n, sizeof(Event), cmp_event);
        qsort(ys, 2 * n, sizeof(ll), cmp_ll);

        int m = 0;
        for (int i = 0; i < 2 * n; ++i) {
            if (i == 0 || ys[i] != ys[i - 1]) ys[m++] = ys[i];
        }

        int segs = (m > 0 ? m - 1 : 0);
        int *cnt = NULL;
        if (segs > 0) cnt = (int *)calloc(segs, sizeof(int));

