        while (i < 2 * n) {
            ll curX = events[i].x;
            area += coveredY * (curX - prevX);

            while (i < 2 * n && events[i].x == curX) {
                int l = lower_bound_ll(ys, m, events[i].y1);
                int r = lower_bound_ll(ys, m, events[i].y2);
                for (int j = l; j < r; ++j) {
                    cnt[j] += events[i].type;
                }
                ++i;
            }

            coveredY = 0;
            for (int j = 0; j < segs; ++j) {
                if (cnt[j] > 0) coveredY += ys[j + 1] - ys[j];
            }
            prevX = curX;
        }

        printf("%lld\n", area);

        free(rects);
        free(events);
        free(ys);
        free(cnt);
    }
