import sys

def union_length(intervals):
    if not intervals:
        return 0
    intervals.sort()
    total = 0
    l, r = intervals[0]
    for nl, nr in intervals[1:]:
        if nl > r:
            total += r - l
            l, r = nl, nr
        else:
            if nr > r:
                r = nr
    total += r - l
    return total

def solve(data):
    it = iter(data)
    out = []
    case_no = 1

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        if n == 0:
            break

        squares = []
        xs = set()

        for _ in range(n):
            x = int(next(it))
            y = int(next(it))
            p = int(next(it))
            x1 = x - p
            x2 = x + p
            y1 = y - p
            y2 = y + p
            squares.append((x1, x2, y1, y2))
            xs.add(x1)
            xs.add(x2)

        xs = sorted(xs)
        area = 0

        for i in range(len(xs) - 1):
            lx = xs[i]
            rx = xs[i + 1]
            if lx == rx:
                continue
            intervals = []
            for x1, x2, y1, y2 in squares:
                if x1 <= lx and rx <= x2:
                    intervals.append((y1, y2))
            covered_y = union_length(intervals)
            area += (rx - lx) * covered_y

        out.append(f"{case_no} {area}")
        case_no += 1

    return "\n".join(out)

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    print(solve(data))

