                squares[i][1] = y - r;
                squares[i][2] = x + r;
                squares[i][3] = y + r;

                ys.add(squares[i][1]);
                ys.add(squares[i][3]);
            }

            // Coordinate compression for y
            ArrayList<Integer> yList = new ArrayList<>(ys);
            int m = yList.size();

            // Events: (x, type, y1, y2) where type=1 for start, type=-1 for end
            ArrayList<int[]> events = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int y1Idx = Collections.binarySearch(yList, squares[i][1]);
                int y2Idx = Collections.binarySearch(yList, squares[i][3]);
                events.add(new int[]{squares[i][0], 1, y1Idx, y2Idx});
                events.add(new int[]{squares[i][2], -1, y1Idx, y2Idx});
            }

            Collections.sort(events, (a, b) -> Integer.compare(a[0], b[0]));

            long area = 0;
            int[] active = new int[m - 1]; // count of active squares covering interval [y_i, y_{i+1})

            for (int i = 0; i < events.size(); i++) {
                int[] event = events.get(i);
                int x = event[0];
                int type = event[1];
                int y1 = event[2];
                int y2 = event[3];

                // Calculate area from previous x to current x
                if (i > 0) {
                    int prevX = events.get(i - 1)[0];
                    long coveredY = 0;
                    for (int j = 0; j < m - 1; j++) {
                        if (active[j] > 0) {
                            coveredY += yList.get(j + 1) - yList.get(j);
                        }
                    }
                    area += coveredY * (x - prevX);
                }

                // Update active intervals
                for (int j = y1; j < y2; j++) {
                    active[j] += type;
                }
            }

            System.out.println(area);
        }
    }
}

import java.util.*;

public class Main {
    static int[] cnt;
    static double[] len;
    static double[] ys;
    static int n;

    static void update(int node, int lo, int hi, int l, int r, int val) {
        if (r <= lo || hi <= l) return;
        if (l <= lo && hi <= r) {
            cnt[node] += val;
        } else {
            int mid = (lo + hi) / 2;
            update(2*node, lo, mid, l, r, val);
            update(2*node+1, mid, hi, l, r, val);
        }
        if (cnt[node] > 0) {
            len[node] = ys[hi] - ys[lo];
        } else if (hi - lo == 1) {
            len[node] = 0;
        } else {
            len[node] = len[2*node] + len[2*node+1];
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int m = sc.nextInt();
            if (m == 0) break;
            double[] x1 = new double[m], x2 = new double[m];
            double[] y1 = new double[m], y2 = new double[m];
            for (int i = 0; i < m; i++) {
                double cx = sc.nextDouble(), cy = sc.nextDouble(), r = sc.nextDouble();
                x1[i] = cx - r; x2[i] = cx + r;
                y1[i] = cy - r; y2[i] = cy + r;
            }
            // Compress y
            TreeSet<Double> ySet = new TreeSet<>();
            for (int i = 0; i < m; i++) { ySet.add(y1[i]); ySet.add(y2[i]); }
            ys = new double[ySet.size()];
            int idx = 0;
            for (double v : ySet) ys[idx++] = v;
            n = ys.length - 1; // number of segments
            Map<Double, Integer> yIdx = new HashMap<>();
            for (int i = 0; i < ys.length; i++) yIdx.put(ys[i], i);

            cnt = new int[4 * n + 4];
            len = new double[4 * n + 4];

            // Events: (x, type, y_lo_idx, y_hi_idx)
            List<double[]> events = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                int yl = yIdx.get(y1[i]), yh = yIdx.get(y2[i]);
                events.add(new double[]{x1[i], 1, yl, yh});
                events.add(new double[]{x2[i], -1, yl, yh});
            }
            events.sort((a, b) -> Double.compare(a[0], b[0]));

            double area = 0;
            double prevX = 0;
            for (int i = 0; i < events.size(); ) {
                double curX = events.get(i)[0];
                area += len[1] * (curX - prevX);
                while (i < events.size() && events.get(i)[0] == curX) {
                    double[] e = events.get(i++);
                    update(1, 0, n, (int)e[2], (int)e[3], (int)e[1]);
                }
                prevX = curX;
            }
            System.out.printf("%.0f%n", area);
        }
    }
}

import java.io.*;
import java.util.*;

/*
 * Union area of axis-aligned squares (L-infinity disks).
 *
 * Each antenna at (x, y) with power p covers:
 *   [x - p, x + p] x [y - p, y + p]
 *
 * We compute the area covered by at least one square using a sweep line on x
 * with coordinate compression on y.
 *
 * Input format assumed:
 *   Multiple datasets.
 *   Each dataset starts with n.
 *   If n == 0, input ends.
 *   Then n lines follow, each containing x y p.
 *
 * Output:
 *   For each dataset, print the total covered area.
 *
 * Area is integral if inputs are integral, but we use long throughout.
 */
public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Event implements Comparable<Event> {
        long x;
        long y1, y2;
        int type; // +1 add, -1 remove

        Event(long x, long y1, long y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }

        public int compareTo(Event o) {
            return Long.compare(this.x, o.x);
        }
    }

    static class SegmentTree {
        int n;
        int[] count;
        long[] covered;
        long[] ys;

        SegmentTree(long[] ys) {
            this.ys = ys;
            this.n = ys.length - 1; // intervals count
            this.count = new int[n * 4 + 5];
            this.covered = new long[n * 4 + 5];
        }

        void update(int node, int l, int r, int ql, int qr, int val) {
            if (ql > r || qr < l || ql > qr) return;
            if (ql <= l && r <= qr) {
                count[node] += val;
                pull(node, l, r);
                return;
            }
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
            pull(node, l, r);
        }

        void pull(int node, int l, int r) {
            if (count[node] > 0) {
                covered[node] = ys[r + 1] - ys[l];
            } else if (l == r) {
                covered[node] = 0;
            } else {
                covered[node] = covered[node << 1] + covered[node << 1 | 1];
            }
        }

        long totalCovered() {
            return n <= 0 ? 0 : covered[1];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        boolean first = true;
        while (true) {
            long nl = fs.nextLong();
            if (nl == Long.MIN_VALUE) break;
            int n = (int) nl;
            if (n == 0) break;

            List<Event> events = new ArrayList<>(2 * n);
            long[] yvals = new long[2 * n];
            int yi = 0;

            for (int i = 0; i < n; i++) {
                long x = fs.nextLong();
                long y = fs.nextLong();
                long p = fs.nextLong();

                long x1 = x - p;
                long x2 = x + p;
                long y1 = y - p;
                long y2 = y + p;

                events.add(new Event(x1, y1, y2, +1));
                events.add(new Event(x2, y1, y2, -1));

                yvals[yi++] = y1;
                yvals[yi++] = y2;
            }

            Arrays.sort(yvals, 0, yi);
            int m = 0;
            for (int i = 0; i < yi; i++) {
                if (i == 0 || yvals[i] != yvals[i - 1]) {
                    yvals[m++] = yvals[i];
                }
            }
            long[] ys = Arrays.copyOf(yvals, m);

            Collections.sort(events);

            SegmentTree st = new SegmentTree(ys);

            long area = 0;
            long prevX = events.get(0).x;
            int idx = 0;

            while (idx < events.size()) {
                long curX = events.get(idx).x;
                long dx = curX - prevX;
                area += dx * st.totalCovered();

                while (idx < events.size() && events.get(idx).x == curX) {
                    Event e = events.get(idx++);
                    int l = lowerBound(ys, e.y1);
                    int r = lowerBound(ys, e.y2) - 1; // [y1, y2)
                    if (l <= r) {
                        st.update(1, 0, st.n - 1, l, r, e.type);
                    }
                }
                prevX = curX;
            }

            if (!first) out.append('\n');
            first = false;
            out.append(area).append('\n');
        }

        System.out.print(out.toString());
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] < key) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}
